let cutoff = datetime(2026-06-10);
let rangeStart = $__timeFrom();
let rangeEnd = $__timeTo();
let effectiveStart = max_of(rangeStart, cutoff);

let excludedPsp = dynamic(["PagoPA", "Ente di Test", "MDC Test"]);

let allowed_tpp =
    TppDataSnapshot
    | where business_name !in~ (excludedPsp)
    | summarize by entity_id;

MessageSnapshot
| where window_start >= effectiveStart and window_start <= rangeEnd
| summarize by origin_id, entity_id, associated_payment
| where associated_payment == true
| where entity_id in (allowed_tpp)
| count;

