let cutoff = datetime(2026-06-10);
let rangeStart = $__timeFrom();
let rangeEnd = $__timeTo();
let effectiveStart = max_of(rangeStart, cutoff);

let excludedPsp = dynamic(["PagoPA", "Ente di Test", "MDC Test"]);

let allowed_tpp =
    TppDataSnapshot
    | where business_name !in~ (excludedPsp)
    | summarize by entity_id;

let accettati =
    MessageSnapshot
    | where window_start >= effectiveStart and window_start <= rangeEnd
    | summarize by origin_id, entity_id, associated_payment
    | where entity_id in (allowed_tpp)
    | summarize
        ['Accettati con pagamento']   = countif(associated_payment == true),
        ['Accettati senza pagamento'] = countif(associated_payment == false);

let scartati =
    MessageVolumeSnapshot
    | where window_start >= effectiveStart and window_start <= rangeEnd
    | summarize
        ['Scartati con pagamento']   = coalesce(sum(discarded_with_payment), 0),
        ['Scartati senza pagamento'] = coalesce(sum(discarded_without_payment), 0);

accettati
| extend _k = 1
| join kind=inner (scartati | extend _k = 1) on _k
| project
    ['Accettati con pagamento'],
    ['Accettati senza pagamento'],
    ['Scartati con pagamento'],
    ['Scartati senza pagamento']

let cutoff = datetime(2026-06-10);
let rangeStart = $__timeFrom();
let rangeEnd = $__timeTo();
let effectiveStart = max_of(rangeStart, cutoff);

let excludedPsp = dynamic(["PagoPA","Ente di Test", "MDC Test"]); // NB: vedi nota sotto

let allowed_tpp =
    TppDataSnapshot
    | where business_name !in~ (excludedPsp)
    | summarize by entity_id;

let tutte_le_tpp =
    TppDataSnapshot
    | where business_name !in~ (excludedPsp)
    | summarize by tpp_id, entity_id, PSP = business_name;

// Universo: coppie (origin_id, entity_id) INVIATE nel periodo, con relativo flag pagamento (piu' recente nel periodo)
let inviate_pairs =
    MessageSnapshot
    | where window_start >= effectiveStart and window_start <= rangeEnd
    | summarize arg_max(window_start, associated_payment) by origin_id, entity_id
    | where entity_id in (allowed_tpp)
    | project origin_id, entity_id, associated_payment;

let known_origins = inviate_pairs | project origin_id, entity_id;

// Lette/Perfezionate: entity_id canonico via origin_id, MAI dal campo nativo delle altre tabelle
let lette_pairs =
    RetrievalIdVolumeSnapshot
    | where window_start >= effectiveStart and window_start <= rangeEnd
    | project origin_id
    | join kind=inner known_origins on origin_id
    | summarize by origin_id, entity_id;

let perfezionate_pairs =
    FinalizedMessageSnapshot
    | where window_start >= effectiveStart and window_start <= rangeEnd
    | join kind=inner tutte_le_tpp on tpp_id
    | join kind=inner known_origins on origin_id
    | summarize by origin_id, entity_id;

let funnel =
    inviate_pairs
    | join kind=leftouter (lette_pairs | extend is_letta = true) on origin_id, entity_id
    | join kind=leftouter (perfezionate_pairs | extend is_perfezionata = true) on origin_id, entity_id
    | project origin_id, entity_id, associated_payment,
        is_inviata = true,
        is_letta = coalesce(is_letta, false),
        is_perfezionata = coalesce(is_perfezionata, false);

tutte_le_tpp
| join kind=leftouter funnel on entity_id
| summarize
    ['Inv. Con Pagamento']    = dcountif(origin_id, associated_payment == true and is_inviata),
    ['Inv. Senza Pagamento']  = dcountif(origin_id, associated_payment == false and is_inviata),
    ['Inviate Totale']        = dcountif(origin_id, is_inviata),
    ['Lette Con Pagamento']   = dcountif(origin_id, associated_payment == true and is_letta),
    ['Lette Senza Pagamento'] = dcountif(origin_id, associated_payment == false and is_letta),
    ['Lette Totale']          = dcountif(origin_id, is_letta),
    ['Perf. Con Pagamento']   = dcountif(origin_id, associated_payment == true and is_perfezionata),
    ['Perf. Senza Pagamento'] = dcountif(origin_id, associated_payment == false and is_perfezionata),
    ['Perfezionate Totale']   = dcountif(origin_id, is_perfezionata)
    by PSP
| order by ['Inviate Totale'] desc

let excludedPsp = dynamic(["PagoPA","Ente di Test", "MDC Test"]);

let payment_map =
    MessageSnapshot
    | summarize arg_max(window_start, associated_payment) by origin_id;
    // Nessun timeFilter per prendere tutto lo storico

let known_origins =
    MessageSnapshot
    | summarize by origin_id;

let perfezionate_con_pagamento =
    FinalizedMessageSnapshot
    | where $__timeFilter(window_start)
    | where origin_id in (known_origins)
    | summarize arg_max(window_start, tpp_id) by origin_id
    | join kind=inner payment_map on origin_id
    | where associated_payment == true
    | summarize ['Perf. Con Pagamento'] = dcount(origin_id) by tpp_id;

let pagate =
    PaymentAttemptSnapshot
    | where $__timeFilter(window_start)
    | summarize ['Notifiche Pagate'] = dcount(origin_id) by tpp_id;

let tutte_le_tpp =
    TppDataSnapshot
    | where business_name !in~ (excludedPsp)
    | summarize by tpp_id, PSP = business_name;

tutte_le_tpp
| join kind=leftouter perfezionate_con_pagamento on tpp_id
| join kind=leftouter pagate on tpp_id
| extend ['Perf. Con Pagamento'] = coalesce(['Perf. Con Pagamento'], 0)
| extend ['Notifiche Pagate']    = coalesce(['Notifiche Pagate'], 0)
| extend ['Tasso di Pagamento']  = iff(['Perf. Con Pagamento'] == 0, 0.0, 
                                            round(100.0 * ['Notifiche Pagate'] / ['Perf. Con Pagamento'], 2))
| project
    PSP,
    ['Notifiche Pagate'],
    ['Tasso di Pagamento']
| order by ['Tasso di Pagamento'] desc
